@app.function(image=image, cpu=2.0, memory=4096, timeout=600, volumes={"/embed": modal.Volume.from_name("sonic-embed")})
def clip_ear(rec):
    import os, subprocess, tempfile, urllib.request, sys
    sys.path.insert(0, "/root")
    tid, url = rec
    try:
        w = tempfile.mkdtemp(); mp3, wav = os.path.join(w, "p.mp3"), os.path.join(w, "c.wav")
        urllib.request.urlretrieve(url, mp3)
        dur = float(subprocess.run(["ffprobe", "-v", "quiet", "-show_entries", "format=duration", "-of", "csv=p=0", mp3], capture_output=True, text=True).stdout.strip() or 0)
        start = max(0.0, (dur - 60) / 2)
        subprocess.run(["ffmpeg", "-y", "-loglevel", "quiet", "-ss", str(start), "-t", "60", "-i", mp3, "-ac", "1", "-ar", "32000", wav], check=True, timeout=120)
        from worker.embed import learned_call
        r = learned_call(wav) or {}
        e = (r.get("ear") or {}).get("v")
        return {"id": tid, "ear": e, "scene": (r.get("scenes") or [[None]])[0][0], "seconds": round(min(dur, 60), 1)}
    except Exception as ex:
        return {"id": tid, "error": type(ex).__name__ + ": " + str(ex)[:120]}


@app.local_entrypoint()
def main():
    import base64, numpy as np, statistics as st
    W = json.load(open("data/walk_ear.json")); ids = W["ids"]; D = W["dims"]
    Q = np.frombuffer(base64.b64decode(W["ear"]), dtype=np.int8).reshape(len(ids), D).astype(np.float32) * np.array(W["scale"], np.float32) / 127
    Q /= np.maximum(np.linalg.norm(Q, axis=1, keepdims=True), 1e-9); at = {t: i for i, t in enumerate(ids)}
    R = list(clip_ear.map(RECORDS, return_exceptions=True)); ok = [r for r in R if isinstance(r, dict) and r.get("ear")]
    bad = [r.get("error") if isinstance(r, dict) else repr(r)[:100] for r in R if not (isinstance(r, dict) and r.get("ear"))]
    ranks, coss, overlap = [], [], []
    for r in ok:
        v = np.array(r["ear"][:D], np.float32); v /= (np.linalg.norm(v) or 1); s = Q @ v; i = at[r["id"]]
        ranks.append(int((s > s[i]).sum()) + 1); coss.append(float(s[i]))
        top_clip = [j for j in np.argsort(-s)[:11] if j != i][:10]; t = Q @ Q[i]; top_full = [j for j in np.argsort(-t)[:11] if j != i][:10]
        overlap.append(len(set(top_clip) & set(top_full)))
    n = len(ok); pct = lambda k: round(sum(1 for x in ranks if x <= k) / n * 100) if n else None
    out = {"records_read": n, "failed": len(bad), "first_errors": bad[:3], "finds_itself_first": pct(1), "in_its_own_top_10": pct(10), "in_its_own_top_100": pct(100),
           "median_rank": (st.median(ranks) if ranks else None), "median_cosine_clip_to_full": (round(st.median(coss), 3) if coss else None),
           "median_shared_neighbours_of_10": (st.median(overlap) if overlap else None), "out_of_records": len(ids)}
    print("::notice title=ear on uploads::" + json.dumps(out)); print("EAR_UPLOAD " + json.dumps(out))
